//! Oracle fuzz test for the original function at 0x148550 (generated by `factory gen`; the spec is the static
//! scan's inference: fix it here if the original faults or writes past a block). The port is `kh2_factory::ported::threshold_band`.
//! Skips without a disc (KH2_ISO or local/iso.txt); fails without one when KH2_REQUIRE_DISC=1.

use kh2_factory::fuzz::*;
use kh2_factory::ported::{BandObj, BandRec};

const SPEC: Spec = Spec {
    addr: 0x148550,
    args: &[Arg::Int(&[]), Arg::Ptr(Block { size: 0x120, fields: &[(0x10d, 1, Kind::Int), (0x114, 4, Kind::Ptr)], subs: &[(0x114, Block { size: 0x50, fields: &[(0x38, 4, Kind::Float), (0x3c, 4, Kind::Float), (0x40, 4, Kind::Float), (0x44, 4, Kind::Float)], subs: &[] })] })],
    floats: 1,
    ret: Ret::None,
    globals: &[],
    stubs: &[],
    // The original reads +0x114 unconditionally.
    nulls: false,
};

#[test]
fn orig_148550_matches_the_game() {
    let Some(st) = fuzz(&SPEC, 4000, |c| {
        // C7: the blocks are the port's own layout types, copied in and out unchanged.
        let mut obj = BandObj::from_bytes(&c.blocks[0]);
        let rec = BandRec::from_bytes(&c.blocks[1]);
        kh2_factory::ported::threshold_band(&mut obj, &rec, c.floats[0]);
        c.blocks[0].copy_from_slice(&obj.0);
        Out::none()
    }) else { return };
    eprintln!("{} cases equal, {} interpreter steps in {:.3} s", st.cases, st.steps, st.secs);
}
